private static int decodeOctets(int i,ByteBuffer bb,StringBuilder sb){
    while (i < bb.limit()) {
        byte b = bb.get(i);
        if ((b & 0x80) == 0) {
            // Single-byte character
            sb.append((char) b);
            i++;
        } else if ((b & 0xE0) == 0xC0) {
            // Two-byte character
            if (i + 1 >= bb.limit()) break;
            sb.append((char) (((b & 0x1F) << 6) | (bb.get(i + 1) & 0x3F)));
            i += 2;
        } else if ((b & 0xF0) == 0xE0) {
            // Three-byte character
            if (i + 2 >= bb.limit()) break;
            sb.append((char) (((b & 0x0F) << 12) | ((bb.get(i + 1) & 0x3F) << 6) | (bb.get(i + 2) & 0x3F)));
            i += 3;
        } else if ((b & 0xF8) == 0xF0) {
            // Four-byte character
            if (i + 3 >= bb.limit()) break;
            int codePoint = ((b & 0x07) << 18) | ((bb.get(i + 1) & 0x3F) << 12) | ((bb.get(i + 2) & 0x3F) << 6) | (bb.get(i + 3) & 0x3F);
            sb.append(Character.toChars(codePoint));
            i += 4;
        } else {
            // Invalid UTF-8 sequence
            i++;
        }
    }
    return i;
}

