        if (headerPart.charAt(i) == '\r' && headerPart.charAt(i + 1) == '\n') {
            return i;
        }
    }
    return -1; // Return -1 if no \r\n sequence is found
}

private int parseEndOfLine(String headerPart, int end) {
    int index = end;
    while (index < headerPart.length()) {
        if (headerPart.charAt(index) == '\r' && index + 1 < headerPart.length() && headerPart.charAt(index + 1) == '\n') {
            return index;
        }
        index++;
    }
    return -1; // Return -1 if no \r\n sequence is found
}

