protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    while (start < end) {
        long nextStart = Math.min(start + FETCH_DATA_DURATION, end);
        timeRanges.add(new TimeRange(start, nextStart));
        start = nextStart;
    }
    return timeRanges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    final long duration = FETCH_DATA_DURATION;

    while (start < end) {
        long newEnd = Math.min(start + duration, end);
        timeRanges.add(new TimeRange(start, newEnd));
        start = newEnd;
    }

    return timeRanges;
}

