protected int removeUnusedNodes(){  
    int removedCount = 0;  
    // Assume 'root' is the root node of the Category tree  
    // and 'isActive()' is a method to check if a node is active  
    Queue<Node> queue = new LinkedList<>();  
    queue.add(root);  
    while (!queue.isEmpty()) {  
        Node currentNode = queue.poll();  
        List<Node> toRemove = new ArrayList<>();  
        for (Node child : currentNode.getChildren()) {  
            if (!child.isActive()) {  
                toRemove.add(child);  
            } else {  
                queue.add(child);  
            }  
        }  
        currentNode.removeChildren(toRemove);  
        removedCount += toRemove.size();  
    }  
    return removedCount;  
}

