GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    List<E> edgeList = new ArrayList<>(tour);
    V startVertex = graph.getEdgeSource(edgeList.get(0));
    SimpleDirectedGraph<V, E> pathGraph = new SimpleDirectedGraph<>(graph.getEdgeFactory());
    pathGraph.addVertex(startVertex);

    V currentVertex = startVertex;
    for (E edge : edgeList) {
        V targetVertex = graph.getEdgeTarget(edge);
        pathGraph.addVertex(targetVertex);
        pathGraph.addEdge(currentVertex, targetVertex, edge);
        currentVertex = targetVertex;
    }

    return new GraphWalk<>(graph, startVertex, currentVertex, edgeList, 0);
}

GraphPath<V,E> function ( Set<E> tour , Graph<V,E> graph ) { 
    List<E> edges = new ArrayList<>(tour);
    V startVertex = graph.getEdgeSource(edges.get(0));
    List<V> vertices = new ArrayList<>();
    vertices.add(startVertex);
    for (E edge : edges) {
        V targetVertex = graph.getEdgeTarget(edge);
        vertices.add(targetVertex);
    }
    return new GraphWalk<>(graph, startVertex, vertices.get(vertices.size() - 1), vertices, edges, 0);
}

