            int offset = 0;
            while (offset < argsDescriptor.length()) {
                char c = argsDescriptor.charAt(offset);
                switch (c) {
                    case 'B': case 'C': case 'F': case 'I': case 'S': case 'Z':
                        // These types take one slot
                        offset += 1;
                        break;
                    case 'D': case 'J':
                        // These types take two slots
                        offset += 1;
                        break;
                    case 'L':
                        // Object types take one slot, skip to the end of the type descriptor
                        offset = argsDescriptor.indexOf(';', offset) + 1;
