private void pop(final String descriptor){
    // Assuming descriptor is a method descriptor and we need to pop the argument types
    int current = 0;
    if (descriptor.charAt(0) == '(') {
        current++; // skip the '('
        while (descriptor.charAt(current) != ')') {
            char c = descriptor.charAt(current++);
            switch (c) {
                case 'B':
                case 'C':
                case 'F':
                case 'I':
                case 'S':
                case 'Z':
                    // These are all 1-word types
                    // pop 1 from the stack
                    break;
                case 'J':
                case 'D':
                    // These are 2-word types
                    // pop 2 from the stack
                    break;
                case 'L':
                case '[':
                    // These are reference types (object or array)
                    // pop 1 from the stack
                    current = descriptor.indexOf(';', current) + 1; // skip to after ';'
                    break;
                default:
                    // Unknown type
                    throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
            }
        }
    } else {
        // descriptor is a field descriptor, just pop 1 or 2 based on the type
        char c = descriptor.charAt(current);
        switch (c) {
            case 'B':
            case 'C':
            case 'F':
            case 'I':
            case 'S':
            case 'Z':
                // These are all 1-word types
                // pop 1 from the stack
                break;
            case 'J':
            case 'D':
                // These are 2-word types
                // pop 2 from the stack
                break;
            case 'L':
            case '[':
                // These are reference types (object or array)
                // pop 1 from the stack
                break;
            default:
                // Unknown type
                throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
        }
    }
}

